export const COMPENDIUM_REALITE_V9_CRAWLERS_PNJ_PDF_1 = [{"id":"pnj-crawlers-antisysteme-p45-encarnacion-miralles","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Encarnación Miralles","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Vagos","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Encarnación Miralles","identity_keys":["Encarnación Miralles","Encarnación Miralles /Mercedes Cadaval","Chapter “Coyotes Locos” : Encarnación Miralles","Mercedes Cadaval"],"statut":"présidence de Motorcycle Club","organisation":"Vagos","age":"34 ans","nationalite":"Mexicaine"},"sections":[{"id":"antisysteme-p45-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Encarnación Miralles"],["Alias / désignation","Chapter “Coyotes Locos” : Encarnación Miralles"],["Âge apparent","34 ans"],["Affiliations","crawlers : gundrivers"],["Nationalité d’origine","Mexicaine"],["Organisation","Vagos"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p45-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Encarnacion est la présidente d’un chapitre des Vagos, les « Coyotes fous ». Son père était un membre éminent du cartel de Tijuana, il détestait les « baronnes » et s’est opposé à leur prise de pouvoir dans le cartel. Quand il fut éliminé lui et sa famille Mercedes Cadaval, de son vrai nom, fut protégée par Ricardo Miralles, un ami de son père, membre des coyotes. Quand les Vagos ont entamé leur guerre pour percer dans le Mexique, la guerre s’y déroulant faisait rage, les motards locaux, contrairement à ceux américains étaient très souvent à aider les familles plus humbles à fuir, parfois revendant les gens aux corporations, parfois plus vertueusement, ils les faisaient passer en Californie. Encarnacion était de ces derniers. Elle fut confrontée aux Vagos et fut poussée à se soumettre à Sean Buckner, le président de l’époque. En échange, il devait l’aider à profiter de la situation pour amoindrir le cartel de San Diejuana, mais il fit tout le contraire une fois les motards mexicains sous sa coupe. Beaucoup de Coyotes sont d’anciens Bandidos vaincus par les Hell Angels ou les Cruisers, mais peu sont Vagos de cœur."}]},{"id":"antisysteme-p45-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p45-kyle-simmons","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kyle Simmons","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Vagos","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Kyle Simmons","identity_keys":["Kyle Simmons","Chapter “Lost Einherjar”: Kyle Simmons"],"statut":"Motards","organisation":"Vagos","age":"","nationalite":"américaine"},"sections":[{"id":"antisysteme-p45-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kyle Simmons"],["Alias / désignation","Chapter “Lost Einherjar”: Kyle Simmons"],["Affiliations","crawler : gundriver – neoslaver"],["Nationalité d’origine","américaine"],["Organisation","Vagos"]]}]},{"id":"antisysteme-p45-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Kyle Simmons est le président des « Los Einherjar » un chapitre très extrême des Vagos. S’ils ont accepté le tournant philosophique plus hispanisant du gang, ils restent très ancrés dans un traditionalisme malsain et intolérant au sein de leur chapitre. Les « Lost Einherjar » sont les meilleurs soldats des Vagos et sont considérés avec un certain respect au sein du gang. Ils sont pourtant des ordures qui ont pour spécialité de soumettre des villages et de revendre les prisonniers."}]},{"id":"antisysteme-p45-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Kurik Simgrnin"],["Nature réelle","whurtenne (naine)"],["Âge réel / complément","65 ans », ?55 ans"],["Statut","présidence de Motorcycle Club"]]},{"type":"p","text":"Kurik n’est pas foncièrement un nain raciste ou spéciste, mais les « Lost Einherjar » sont un chapitre de motards exclusivement nains, rebelles à toute autorité du conseil des Anciens ou toute faction, ils survivent ainsi, se protégeant entre eux, au sein d’une communauté restreinte mais soudée exclusivement whurtenne. La revente d’esclave est surtout un moyen de justifier une recherche des leurs et de trier. Ce sont d’excellents combattants qui descendent de partisans de Motsognir ayant renoncé à servir le roi-sorcier des profondeurs et ne trouvant pas leur place auprès des autres nains."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p46-raghnaid-peutan","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Raghnaid Peutan","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Sons of Silence","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Raghnaid Peutan","identity_keys":["Raghnaid Peutan","Queen of the Ragnarok: Raghnaid Peutan"],"statut":"Motards","organisation":"Sons of Silence","age":"29 ans- ???","nationalite":"Norvégienne"},"sections":[{"id":"antisysteme-p46-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Raghnaid Peutan"],["Alias / désignation","Queen of the Ragnarok: Raghnaid Peutan"],["Âge apparent","29 ans- ???"],["Affiliations","crawlers Gundrivers"],["Nationalité d’origine","Norvégienne"],["Organisation","Sons of Silence"]]}]},{"id":"antisysteme-p46-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Les « Sons of Silence » ont été fondé dans les années 1966. Misogyne, raciste et violent, c’était un gang de motards criminalisés comme quelques autres. Nativement issu du Colorado bien que s’étant prodigieusement répandu, ce club a participé à la grande guerre des motards aux Etats-Unis au début des années 2030. Pas seulement en Californie mais sur toutes les grandes routes des Etats-Unis, les motards ont pris des stations puis des villages routiers. Les Sons ont vaincu dans le Colorado, avant de se jeter sur la Californie, centre névralgique de nombre de marché illégaux. Quand Todd Sheperd, le grand président a été assassiné par Arthur Bartram et tout le chapitre des « Crying sons » massacré, une crise ravagea le club. La petite amie de Sheperd, Raghnaid, une réfugiée européenne, défendit le QG avec quelques régulières. Elles arrachèrent dans le sang et la sueur leur droit de porter le cuir et marchèrent sur les Hell Angels de « San Iron Paulo », un village motard, une cinquantaine de « Valkyries » de cuir et de chrome massacrèrent et incendièrent le village durant une nuit entière. Crainte, elle s’installa comme présidente des Sons car aucun n’osa lui rappeler qu’ils n’acceptaient pas les femmes. Amazone, c’est une des 8 reines servant Angrboda et vénérant Katja. Elle était amie avec Brunehilde."}]},{"id":"antisysteme-p46-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","Amazone"],["Statut","Chef de Motorcycle Club"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p46-eamonn-mac-cearain","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Eamonn Mac Cearáin","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Sons of Silence","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Eamonn Mac Cearáin","identity_keys":["Eamonn Mac Cearáin","Chapter “Bloody Clover” : Eamonn Mac Cearáin"],"statut":"présidence de Motorcycle Club","organisation":"Sons of Silence","age":"34 ans  -","nationalite":"Irlandaise"},"sections":[{"id":"antisysteme-p46-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Eamonn Mac Cearáin"],["Alias / désignation","Chapter “Bloody Clover” : Eamonn Mac Cearáin"],["Âge apparent","34 ans  -"],["Affiliations","crawlers : Gundrivers"],["Nationalité d’origine","Irlandaise"],["Organisation","Sons of Silence"],["Statut","présidence de Motorcycle Club"],["Nature","humaine-kelta"]]}]},{"id":"antisysteme-p46-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Eamonn est une des pires raclures que le monde puisse connaitre. Né en Irlande, c’est un cousin de Deaman et Siobhain à quelques degrés. Enfant, il était convaincu de voir des esprits et des spectres alors sa mère essaya nombre de thérapies qu’il rejeta avec violence. Dès qu’il fut majeur, Il tenta de s’approcher de l’IRA véritable et l’intégra plus tardivement après quelques années de criminalité médiocre. Il fut envoyé aux Etats-Unis pour une mission mais n’en revint jamais. Ami avec Todd larsen, il se maria avec Yazmeen Oliver, une ancienne camarade de classe de Dina Page qu’il avait sous sa coupe, devenant Américain. Il erra entre gang, IRA, motards, neonazi, devenant très ami avec Todd Sheperd, le président des Sons of Silence. Il comptait le trahir une fois le gang bien lié à l’IRA et aux néofascistes des prisons américaines, un réseau parfait pour bosser avec Larsen maisla grande guerre des motards ruina ses plans et Raghnaid lui dama le pion quant à la présidence suprême."}]},{"id":"antisysteme-p46-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"Demi-Kelta, il est le fils de Sharfeidd, un kelta harfang assez ancien et totalement loyal à Morrighan. Lui n’a pas conscience d ce qu’il est hormis qu’il voit des choses, en revanche c’est une ordure, il a prostitué ses sœurs et sa mère assez jeune pour avoir de quoi s’offrir une voiture et une arme à feu, pour cela, son propre géniteur, qui avait aimé l’humaine, le déteste de tout son être."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p47-rike-kuechler","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Rike Kuechler","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Sons of Silence","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Rike Kuechler","identity_keys":["Rike Kuechler","Chapter “Noisy Daughters” : Rike Kuechler"],"statut":"présidence de Motorcycle Club","organisation":"Sons of Silence","age":"26 ans","nationalite":"allemande"},"sections":[{"id":"antisysteme-p47-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Rike Kuechler"],["Alias / désignation","Chapter “Noisy Daughters” : Rike Kuechler"],["Âge apparent","26 ans"],["Affiliations","crawlers : gundrivers"],["Nationalité d’origine","allemande"],["Organisation","Sons of Silence"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p47-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Rike Kuechler est une ancienne pute à motards. Lors de la grande guerre des moteurs, elle était amie avec Raghnaid et a attaqué le village des Hell Angels avec elle, elle n’avait que 21 ans mais déjà ses compétentes semblaient exceptionnelles pour ce qui était de racasser des cranes et briser des os. Quand elle vient à Los Angeles ce n’est que pour s’entrainer physiquement, c’est une droguée de l’effort physique et de la musculation. Elle aime son corps et les muscles, tous les muscles, hommes, femmes, même les taureaux sous hormones la font fantasmer, seule importe la fibre musculaire bien dense. Elle répugne la maigreur et l’obésité mais aussi les gens de petite taille ou malformés. Elle était neonazi dans sa jeunesse et c’est pour ça qu’elle a une profonde intolérance mais elle assume sa « musculosexualité » pleinement et comprend que les mentalités comme celle qu’elle avait sont stupides. Son plus grand fantasme est le général Ashorn mais plus généralement tous les vétérans, elle-même n’ayant pas fait la guerre. Outre les muscles, sa moto, Miranda, est la seconde chose la plus précieuse pour elle."}]},{"id":"antisysteme-p47-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p47-cannon-mullins","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Cannon Mullins","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Sons of Silence","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Cannon Mullins","identity_keys":["Cannon Mullins","Chapter “Sons of Spunk”: Cannon Mullins"],"statut":"présidence de Motorcycle Club","organisation":"Sons of Silence","age":"","nationalite":"américaine"},"sections":[{"id":"antisysteme-p47-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Cannon Mullins"],["Alias / désignation","Chapter “Sons of Spunk”: Cannon Mullins"],["Affiliations","crawler : gundriver"],["Nationalité d’origine","américaine"],["Organisation","Sons of Silence"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p47-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Cannon Mullins est le président des « fis de l’Audace ». Ses motards sont des caricatures dignes de sortir de Madmax, ils cherchent à mourir dans le plus grand des fracas et se droguent, boivent et s’augmentent physiquement jusqu’à suffisamment vriller pour ne plus avoir peur. Force incontrôlable des Sons of silence, ce chapitre terrifiant est comme une bande de chiens sauvage que Raghnaid lance sur ses pires ennemis, Cannon a d’ailleurs deux armes de prédilection la tronçonneuse à dents usées et le canon anti￾aérien dont il équipe tous ses camions et ses 4x4. Il y a deux choses à ne jamais dire à Cannon : la première est d’évoquer qu’il n’a fait qu’une semaine en Corée, avant de déserter peu avant les grands massacres, pour un « Fils de l’Audace », l’ironie semble totale. La seconde chose à ne pas évoquer c’est de le défier, même pour le jeu, Cannon est tellement complexé de s désertion et de sa couardise que tous ceux qui le défient finissent sous sa tronçonneuse émoussée, à voir leur corps partir en lambeaux sur les dents les moins abimées de la tronçonneuse. Il ne se bat jamais lui-même malgré sa carrure, quand on le défi, il ordonne qu’on attrape l’avorton ayant osé et l’exécute avec autant de lâcheté que de sadisme. Il est gardé par Raghnaid car la dévotion de ses hommes est immense, eux ont la bravoure qu’il n’a pas."}]},{"id":"antisysteme-p47-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","45 ans »"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p48-zaketa-harris","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Zaketa Harris","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Sons of Legba","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Zaketa Harris","identity_keys":["Zaketa Harris","Baron moteur: Zaketa Harris"],"statut":"Motards","organisation":"Sons of Legba","age":"39 ans- ???","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p48-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Zaketa Harris"],["Alias / désignation","Baron moteur: Zaketa Harris"],["Âge apparent","39 ans- ???"],["Affiliations","crawlers Gundrivers"],["Nationalité d’origine","Américaine"],["Organisation","Sons of Legba"]]}]},{"id":"antisysteme-p48-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Les « Sons of Legba » ont été fondé en 2025, pendant la guerre de 22-28. En réponse au début du rejet des vétérans, les afroaméricains n’avaient pas de structure similaire à un club de motards, ils avaient des gangs et des familles mais étaient rejetés d’autres fraternités. Zaketa pendant une permission, rassembla des vétérans blessés pour former les « fils de Legba », même si on les appelle plus communément « Children of Legba », étant donné la forte présente féminine dans le club."}]},{"id":"antisysteme-p48-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Baron moteur"],["Nature réelle","Guédé (psychopompe)"],["Statut","Chef de Motorcycle Club"]]},{"type":"p","text":"« Baron moteur » ou parfois « Baron Blast » est un Guédé, un esprit de la mort, un psychopompe donc, une famille d’êtres qui ne sont pas des spectres, pas des anges ou des démons, mais pas des nymphes pour autant, à mi-chemin entre nymphe et voyageurs. « Moteur » est assez jeune puisqu’il est né à l’ère industrielle, il sert à récupérer les âmes sur le bord de la route, ceux crashés au volant ou sur une moto. Il a généralement une moto ultra customisée avec de l’or et du chrome et un corbillard dans le même ton. Sa femme est la « baronne routière », elle a un camion 35 tonnes customisé et tourne en grande Californie pour « péter sa gueule » à son mari dit-elle aux âmes n’ayant pas encore réalisé leur mort."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p48-annushka-lyninka-maxinovna","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Annushka Lyninka Maxinovna","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Sons of Legba","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Annushka Lyninka Maxinovna","identity_keys":["Annushka Lyninka Maxinovna","Chapter “Daughters Of Eshu” : Annushka Lyninka Maxinovna"],"statut":"présidence de Motorcycle Club","organisation":"Sons of Legba","age":"38 ans  -","nationalite":"Russe"},"sections":[{"id":"antisysteme-p48-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Annushka Lyninka Maxinovna"],["Alias / désignation","Chapter “Daughters Of Eshu” : Annushka Lyninka Maxinovna"],["Âge apparent","38 ans  -"],["Affiliations","crawlers : Gundrivers"],["Nationalité d’origine","Russe"],["Organisation","Sons of Legba"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p48-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Annushka est née en 1997, de riches parents américains. Hélas, ils firent naufrage après que leur meilleur ami, Shuji KASHIWA (riche président de la corporation Lao-Kashiwa bank) ne leur ai prêté un voilier. Le naufrage se fit dans les îles Kouriles, où Shuji avait envoyé Tomas et Jashanna Garnett, les médecins russes s’occupèrent de l’accouchement de Jashanna. Annushka débuta sa vie en Russie, l’ignorant mais traquée par les hommes de mains de Shuji qui refusait qu’elle hérite de Tomas pour les parts de leurs entreprises."}]},{"id":"antisysteme-p48-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"C’est le système corrompu et indépendant russe qui la protégea des influences japonaises. En 2011, alors qu’elle avait 14 ans, sa tante, Zekera Collins arriva à la récupérer officiellement, Annushka débarquant à Los Angeles sans parler un mot d’anglais, à peine le japonais et surtout le russe. Rejetée par cette différence linguistique, elle se rapprocha de parias et finit par intégrer un gang : les reapers, mais elle le quitta assez vite, une jeune blonde lui piquant la vedette. Athlète confirmée en lutte, elle ne pu participer aux JO à cause des soucis de nationalité. Pendant la guerre, elle échappa à la conscription forcée en intégrant des renégats motards puis intégra les « Sons of Legba ». Elle est un atout pour eux, car a mafia russe négocie peu avec les afro-américains sauf elle."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p49-lemaun-cross","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"LeMaun Cross","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Sons of Legba","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"LeMaun Cross","identity_keys":["LeMaun Cross","Chapter “Wolfs of Death” : LeMaun Cross"],"statut":"Motards","organisation":"Sons of Legba","age":"56 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p49-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","LeMaun Cross"],["Alias / désignation","Chapter “Wolfs of Death” : LeMaun Cross"],["Âge apparent","56 ans"],["Affiliations","crawlers : gundrivers"],["Nationalité d’origine","américaine"],["Organisation","Sons of Legba"]]}]},{"id":"antisysteme-p49-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"LeMaun Cross est un sanguinaire président de gang de motards. On sait assez peu de choses sur lui, si ce n’est que c’est un ancien policier de Washington qui a été condamné pour corruption, violence et abus de pouvoir. Il fut incriminé pour double homicide. Emprisonné 15 ans, il est un des rares ex-policiers à survivre en prison. Relâché en 2025 pour être jeté dans la secrète « Sentenced army », quand le gouvernement américain s’imagina qu’envoyer des milliers de détenu en Corée pourrait aider, n’imaginant pas 95% de désertion comme résultat, avec 41% de meurtres d’officiers en charge dans cette armée. Lui refusa de fuir et après un an de combat, sans logistique, cette armée étant condamnée à mort, il a été rapatrié en attendant une révision de peine pour son héroïsme, mais la Justice américaine s’étant cassée la gueule pendant la guerre, il a juste été transféré à Corcoran, rejoignant le gang carcéral de Katell avant d’être libéré à la suite d’une magouille corporatiste le rachetant pour une mission visant à buter Dina Page. Cette fois, il déserta et se réfugia chez les bikers."}]},{"id":"antisysteme-p49-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","loup-garou (pelage roux)"],["Statut","présidence de Motorcycle Club"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p49-toxicity-norton","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Toxicity Norton","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Sons of Legba","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Toxicity Norton","identity_keys":["Toxicity Norton","Chapter “Chaos Skull”: Toxicity Norton"],"statut":"Motards","organisation":"Sons of Legba","age":"","nationalite":"américaine"},"sections":[{"id":"antisysteme-p49-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Toxicity Norton"],["Alias / désignation","Chapter “Chaos Skull”: Toxicity Norton"],["Affiliations","crawler : gundriver"],["Nationalité d’origine","américaine"],["Organisation","Sons of Legba"]]}]},{"id":"antisysteme-p49-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"pouvoir angélique : le poison céleste Statut : présidence de Motorcycle Club Toxicity est née d’une mère droguée qui a mal vécu sa grossesse, l’appelant ainsi avant de l’abandonner. C’est une femme qui n’a jamais été aimée ni respectée. Dans l’orphelinat, elle a été agressée par un éducateur, elle lui a ouvert le pénis sur la longueur avec un bout de vitre, elle n’avait que 12 ans. Placée en maison de correction, elle s’est enfoncée dans la violence et les tentatives de suicide. Boxeuse de moindre envergure, elle a fait des douzaines de boulots avant d’aller au front. Elle n’avait aucune formation militaire mais a adoré la fraternité militaire, après la guerre, son syndrome post-traumatique l’a rendu incapable de sortir dans la rue. Après une tentative ratée, elle a décidé de joindre les Sons of Legba."}]},{"id":"antisysteme-p49-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Roshielle"],["Nature réelle","Angelus (séraphine)"],["Âge réel / complément","31 ans »"]]},{"type":"p","text":"Morte après la guerre, elle a été possédée par Roshielle, la séraphine d’Azrael, une des plus fidèles créature servant l’Archange de la Mort. Elle a collaboré avec le Baron Moteur de suite. Elle est peu aimée des angelus, daemons et mages liés aux motards car ses pouvoirs sont très efficaces contre eux, son poison céleste ronge l’âme peu importe l’Hologramme pour peu qu’elle blesse assez gravement et un des premiers effets est de réduire les pouvoirs les plus immatériels"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p50-honda-daisuke","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Honda Daisuke","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Onikishi","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Honda Daisuke","identity_keys":["Honda Daisuke","The Samurai: Honda Daisuke"],"statut":"Chef de Motorcycle Club","organisation":"Onikishi","age":"49 ans- ???","nationalite":"Japonaise"},"sections":[{"id":"antisysteme-p50-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Honda Daisuke"],["Alias / désignation","The Samurai: Honda Daisuke"],["Âge apparent","49 ans- ???"],["Affiliations","crawlers Gundrivers"],["Nationalité d’origine","Japonaise"],["Organisation","Onikishi"],["Statut","Chef de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p50-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Les « Onikishi » ont été fondé en 2030, c’est un gang de motards assez récent. Ils puisent leurs origines dans les nombreux clans Yakuza que le clan majeur en Californie a totalement anéanti après la guerre, une foule non négligeable de vétérans japonais, liés aux Yakuza s’est retrouvée incapable de joindre la moindre mafia. Daisuke était un officier yakuza puis militaire pendant la guerre, quand on tua son père en Californie, il réalisa que Los Angeles était un piège mortel et pendant plusieurs mois il échappa aux ennemis de son clan en parcourant l’état à moto, suivi de quelques autres japonais et coréens dans sa situation, ils finirent par former ce gang."}]},{"id":"antisysteme-p50-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"Le code d’honneur des Onikishi est parfois hallucinant et totalement factice, derrière l’image de samurai modernes, ils ne sont que des vétérans passés criminels, paranoïaques et souvent racistes. Tous les Onikishi reçoivent un « katana » (sabre), un « uma » (cheval), un « yumi » (arc) et un « sashimono » (une bannière) autrement dit ; une arme blanche, une moto, un fusil et un blouson de cuir aux couleurs du gang. Ils se prennent pour des samurais idéalisés"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p50-miyashiro-kamiko","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Miyashiro Kamiko","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Onikishi","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Miyashiro Kamiko","identity_keys":["Miyashiro Kamiko","Chapter “Red Oni” : Miyashiro Kamiko"],"statut":"Motards","organisation":"Onikishi","age":"28 ans  -","nationalite":"japonaise"},"sections":[{"id":"antisysteme-p50-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Miyashiro Kamiko"],["Alias / désignation","Chapter “Red Oni” : Miyashiro Kamiko"],["Âge apparent","28 ans  -"],["Affiliations","crawlers : Gundrivers"],["Nationalité d’origine","japonaise"],["Organisation","Onikishi"]]}]},{"id":"antisysteme-p50-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Kamiko est une terrifiante motarde des Onikishi. Elle a le « fourreau sanglant » et détient le chapitre des « red Oni ». Chaque président et grand officier Onikishi possède un katana conçu par Sehdia craft. Elle est une des plus sanguinaires au sein du gang et possède plusieurs amantes et amants puisqu’elle se déclare polygame et néopaïenne."}]},{"id":"antisysteme-p50-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Bune - Hojo Masako"],["Nature réelle","daemons"],["Statut","ex-duchesse daemoniaque ("]]},{"type":"p","text":"L’ancienne duchesse démoniaque Bune est connue pour être un grand-duc représenté par un dragon à trois têtes. Elle est capable de sublimer le courage et l’éloquence de ceux qu’elle bénit. Elle succéda au précédent Bune sans entrer dans l’enfer de Lucifer, déchu quand Masako, épouse de Minamoto no Yoritomo devint une daemone. Ce n’est pas Lucifer qui la « créa » en tant que daemone mais Belial, malgré les oppositions avec son vassal lumineux, la reine des dieux n’at aucun intérêt à voir une faction infernale détruite, entretenant donc les forces de Lucifer chaque siècle."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p51-shitomada-kiyoemon","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Shitomada Kiyoemon","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Onikishi","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Shitomada Kiyoemon","identity_keys":["Shitomada Kiyoemon","Chapter “Last Bosozoku”: Shitomada Kiyoemon"],"statut":"présidence de Motorcycle Club","organisation":"Onikishi","age":"69 ans","nationalite":"japonaise"},"sections":[{"id":"antisysteme-p51-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Shitomada Kiyoemon"],["Alias / désignation","Chapter “Last Bosozoku”: Shitomada Kiyoemon"],["Âge apparent","69 ans"],["Affiliations","crawlers : gundrivers"],["Nationalité d’origine","japonaise"],["Organisation","Onikishi"],["Statut","présidence de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p51-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Kiyoemon est un ancien Bosozuku des années 1980. Brute de 19 ans en 1985 quand il est pratiquement tué par des yakuzas qu’il avait défiés, il vit la lente désuétude de son mode de vie dans les années 1990 et 2000. En 2007, à 41 ans, n’ayant pu intégrer ni l’armée ni la police vu son passé de criminel, il était donc Handyman (homme à tout faire) jusqu’à ce que le clan Yakuza de l’Orochi Fukuoka (à Fukuoka, plus grande ville de Kyushu), ne vienne faire sa loi dans son quartier. Enfilant son grand manteau blanc et prenant ses couteaux de sushiman, il découpa les phalanges de 46 mafieux et de sa batte en envoya 21 à l’hôpital. Envoyé 15 ans en prison pour cela, il fut libéré pour joindre la défense Japonaise face aux Nord￾Coréens. Après la guerre, en 2028, il se retrouvé déporté en Californie, à 62 ans, il rassembla ses économies pour monter son sushibar à Los Angeles, mais les mafias locales ne le laissèrent pas en paix, 21 connards à l’hôpital plus tard, il vola une moto et erra, volant selon sa faim. Kiyoemon est l’héritier du style Shitomada, art martial dérivé du clan Shi, d’où sa force de combat malgré son âge, fort depuis l’enfance et encore maintenant, ayant le niveau d’un maître puisqu’il en est un."}]},{"id":"antisysteme-p51-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p51-yokoyama-shinobu-yo-jin-joo","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Yokoyama Shinobu - Yo Jin-Joo","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Onikishi","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Yokoyama Shinobu - Yo Jin-Joo","identity_keys":["Yokoyama Shinobu - Yo Jin-Joo","Chapter “Green Oni”: Yokoyama Shinobu"],"statut":"présidence de Motorcycle Club","organisation":"Onikishi","age":"","nationalite":"Coréenne"},"sections":[{"id":"antisysteme-p51-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Yokoyama Shinobu - Yo Jin-Joo"],["Alias / désignation","Chapter “Green Oni”: Yokoyama Shinobu"],["Affiliations","crawler : gundriver"],["Nationalité d’origine","Coréenne"],["Organisation","Onikishi"],["Statut","présidence de Motorcycle Club"],["Nature","Humaine (génétiquement altérée)"]]}]},{"id":"antisysteme-p51-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Jin-Joo est née en Corée du nord en 1996. Elle a été élevée selon un programme d’entrainement d’orphelins et a été menée au paroxysme de l’Humanité. En 2022, âgée de 26 ans, elle était un solda parfait et était des forces frappant le Japon. Pendant la reconquête de ce pays par les forces alliées, Jin￾Joo a commencé à réellement douter de ses supérieurs, en effet, membre de l’élite, elle côtoyait souvent le général Kang Sung-Hyung, assez pour réaliser qu’il utilisait des pouvoirs psychiques sur elle et les autres orphelins du programme et assez pour comprendre qu’il n’était pas humain. Désertant dès que possible, elle savait parfaitement parler Japonais heureusement et s’est faite passée pour une résistante afin d’être déportée aux Etats-Unis."}]},{"id":"antisysteme-p51-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","39 ans »"]]},{"type":"p","text":"Elle usurpa l’identité de Yokoyama Shinobu pour cela, hélas pour elle, cette dernière avait hérité d’un des Katana de fléaux et les dons mentaux de Jin-Joo résonnaient avec cet héritage. Elle le vendit dès que possible lors d’enchères. Elle préféra rejoindre les Onikishi pour débuter une nouvelle vie, cachant son passé nordco avec plus de colère que de honte, essayant d’aider le Xenoshield dès que possible. Elle parle coréens, japonais, chinois, russe et anglais parfaitement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p52-wenona","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Wenona","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Last Crows","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Wenona","identity_keys":["Wenona","The mother black eagle : Wenona"],"statut":"Chef de Motorcycle Club","organisation":"Last Crows","age":"45 ans- ???","nationalite":"américaine"},"sections":[{"id":"antisysteme-p52-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Wenona"],["Alias / désignation","The mother black eagle : Wenona"],["Âge apparent","45 ans- ???"],["Affiliations","crawlers Gundrivers"],["Nationalité d’origine","américaine"],["Organisation","Last Crows"],["Statut","Chef de Motorcycle Club"],["Nature","humaine"]]}]},{"id":"antisysteme-p52-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Les « last crows » sont des bikers particulièrement violents, ils n’ont pas de territoire propre, ils errent à leur convenance du sud du Canada jusqu’au Mexique. Wenona est la chef, c’est une motarde et une chamane."}]},{"id":"antisysteme-p52-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"Son père est le célèbre chasseur « Chaman », elle ne chasse pas réellement les créatures mais quand ses chapitres tombent sur une piste, elle ne rechigne pas à les envoyer. Tous les « Last Crows » sont un peu initiés aux savoirs folkloriques et quelques fondamentaux de la chasse occulte. Wenona est une dure à cuir, elle n’a jamais su se laisser faire. Capturée enfant par une garou corrompue voulant négocier avec le « Chaman » en ayant un otage, Wenona, âgée de 8 ans tua la garou, nul ne sait trop comment, probablement aidée par un esprit protecteur. Pour elle, son vrai père est Delwynn McFarlane, un motard, des Black Crows, qui la récupéra après la capture par la créature. Elle a un lien sororal avec Ciara McFarlane, la fille de Delwynn, dont elle voit la nature, en effet, les yeux de Wenona voient à travers le voile naturellement si elle le désire. Elle le cache à Ciara et son père mais l’esprit qui la protège n’a rien de saint, Thaagnno, un Mageius corrompu par Thul et ayant asservi des âmes pour devenir un nouveau type de fléau."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p52-ciara-macfarlane","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ciara MacFarlane","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Last Crows","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Ciara MacFarlane","identity_keys":["Ciara MacFarlane","Solitaire : “True Crow” : Ciara McFarlane"],"statut":"Motards","organisation":"Last Crows","age":"42 ans  -","nationalite":"américaine"},"sections":[{"id":"antisysteme-p52-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ciara MacFarlane"],["Alias / désignation","Solitaire : “True Crow” : Ciara McFarlane"],["Âge apparent","42 ans  -"],["Affiliations","crawlers : Gundrivers/ chasseuse"],["Nationalité d’origine","américaine"],["Organisation","Last Crows"]]}]},{"id":"antisysteme-p52-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ciara est la fille de Delwynn McFarlane et de Ravenna Blake. Abandonnée jeune par sa mère, son père motard la trimballa dans son sidecar jusqu’à ce qu’elle s’inscrive au collège, en Californie, détestant le Nevada où elle naquit. Hélas, à 16 ans, son père disparut dans un « accident », tué par des marchands d’armes russes. Plutôt que vivre chez les tueurs de Wenona, son amie d’enfance, elle garda la moto et s’échappa aux services sociaux pour vivre parfois avec les motards, souvent seule, rencontrant Naalnish, son meilleur ami, un esprit corbeau qu’elle sauva. Avec son errance, elle devint une des meilleures chasseuses du monde, Naalnish lui amenant des bons tuyaux, des armes, des matériaux."}]},{"id":"antisysteme-p52-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","demi-déesse (humaine)"],["Statut","légende vivante"]]},{"type":"p","text":"Elle a fait la guerre de 22-28 dans les troupes mercenaires, elle a contribué à l’essor des néopaïens, ayant toujours vu des esprits et des daemons ou des angelus depuis son enfance. Elle intégra l’Association par hasard et monta dans le hunt15 pour pouvoir détruire « Vargrunda », une amazone corrompue et récupérer les restes de la lance de Brunhilde qu’elle possédait afin de débloquer ses pouvoirs. Elle voue une haine rare au Mage Saint-Germain, le contrôle du temps lui faisant horreur."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p53-meilir-yarwood","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Meilir Yarwood","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Last Crows","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Meilir Yarwood","identity_keys":["Meilir Yarwood","Chapter “legion of Ravens”: Meilir Yarwood"],"statut":"Motards","organisation":"Last Crows","age":"49 ans","nationalite":"galloise"},"sections":[{"id":"antisysteme-p53-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Meilir Yarwood"],["Alias / désignation","Chapter “legion of Ravens”: Meilir Yarwood"],["Âge apparent","49 ans"],["Affiliations","crawlers : gundrivers/ mercs"],["Nationalité d’origine","galloise"],["Organisation","Last Crows"]]}]},{"id":"antisysteme-p53-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Meilir est un gallois qui a émigré aux Etats-Unis pour fuir une vie d’ennui. il a longtemps été dans les « black crow », la bande de motard, où il était un très bon ami de Delwynn, il a souvent veillé sur Ciara avant qu’elle ne fuît à la disparition de son père. Bien qu’il ait tenté d’intégrer Ushkoll quelques années avant la guerre, il n’y resta pas après 2028."}]},{"id":"antisysteme-p53-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Munin"],["Nature réelle","keltas"],["Statut","présidence de Motorcycle Club"]]},{"type":"p","text":"Kelta c’est le frère d’Hugin, il se nomme Munin et c’est un des kelta les plus anciens sur Terre, chargé de surveiller Ciara quand Hugin le fut, plus tard, pour Siobhain, il a toujours combattu Naalnish, sachant bien que l’esprit corbeau sournois voulait utiliser les filles de Morrighan Bien que président de MC, sa dévotion ne va qu’à Morrighan et à la moindre demande, il obéit. On l’appelle « mémoire » car il a le don unique de tout retenir de manière ordonnée et utile, ça fait de lui un adversaire terrifiant car il a peu de chose qu’il ne connait pas et donc qu’il ne peut contrer. Il était amoureux de la reine atlante d’hyperborée, Hildeveig, mais à la mort de Brunhilde, elle essaya de le tuer, rejetant les daemons et esprits de Morrighan."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p53-zack-littlebear","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Zack LittleBear","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Motards","Last Crows","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Zack LittleBear","identity_keys":["Zack LittleBear","Chapter “Wolfs&Eagles”: Zack LittleBear"],"statut":"présidence de Motorcycle Club","organisation":"Last Crows","age":"","nationalite":"américaine"},"sections":[{"id":"antisysteme-p53-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Zack LittleBear"],["Alias / désignation","Chapter “Wolfs&Eagles”: Zack LittleBear"],["Affiliations","crawler : gundriver"],["Nationalité d’origine","américaine"],["Organisation","Last Crows"],["Statut","présidence de Motorcycle Club"],["Nature","Humaine"]]}]},{"id":"antisysteme-p53-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Zack est un des fils de Khaashtay non pas l’actuel, mais le précédent."}]},{"id":"antisysteme-p53-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","29 ans »"]]},{"type":"p","text":"Il connait les loups-garous mais n’en est pas un. Toute son enfance, il rêvait de devenir, les soirs de pleine lune, une créature surpuissante et sauvage. Il a appris à se battre, la survie, il se mettait souvent en danger et quand son père fut tué par John Sandrock, il fut mis de coté par la meute, afin de le protéger en tant qu’humain autant que pour sauver leur, le nouveau grand meneur étant assez sanguinaire. Trop jeune pour faire la guerre de 22-28, Zack erra longuement avant d’être tabassé par Wenoma dans un bar, humilié il la braqua avec une arme alors qu’il était encore au sol, avec un sang froid inégalable, Wenoma vida sa bière dans le canon du flingue braqué vers elle et lui proposa de payer les frais pour ses dents pétées en échange de devenir son larbin, ce qu’il accepta. Il prit de l’importance dans les Last Crows, et créa son propre chapitre. Il a été contacté par des vampires afin de l’aider à se venger, étant fils de garou il est compatible avec le sang vampirique et pourrait en devenir un, l’Ihuito Meztzi cherche à le séduire pour l’utiliser et l’idée de de devenir vampire pour tuer John Sandrock reste très présente dans son quotidien."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p56-amalia-carson","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Amalia Carson","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Underwater Nation","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Amalia Carson","identity_keys":["Amalia Carson","l’héritière : Amalia Carson"],"statut":"Enders","organisation":"Underwater Nation","age":"22 ans","nationalite":"danoise"},"sections":[{"id":"antisysteme-p56-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Amalia Carson"],["Alias / désignation","l’héritière : Amalia Carson"],["Âge apparent","22 ans"],["Affiliations","crawlers : enders / religieux (néopaïens)"],["Nationalité d’origine","danoise"],["Organisation","Underwater Nation"]]}]},{"id":"antisysteme-p56-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Amalia est milliardaire, son père était le vice-président d’Ocean Master et il aurait été lâchement assassiné par ses collaborateurs. Heureusement, Amalia hérita sans qu’ils n’accèdent à l’argent mis de côté. Remontée contre Ocean master et Seawares , elle est une figure néopaïenne qui lutte contre l’exploitation de la mer et elle finance donc lourdement « l’underwater nation »."}]},{"id":"antisysteme-p56-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Amphitrite"],["Nature réelle","Nymphe (néréide)"],["Âge réel / complément","???"],["Statut","Soutien financier"]]},{"type":"p","text":"Gaîa pour la terre, Coronis pour le ciel, amphitrite pour les mers, telle est la trinité des plus puissantes et anciennes nymphes ayant été et étant encore. La nymphe des mers était l’amante et l’alliée d’Alabor, la déesse des flots, mais les dieux se détournant de leur lutte contre les serviteurs des fléaux pour combattre plus activement les Archanges, elle se détourna de cette alliance et se rapprocha de Thul faute de soutien pour y faire face. S’il a fini par être emprisonné, cette tentative de rapprochement coûta cher à Amphitrite tant chez les nymphes qu’avec les dieux, elle aide la fille d’Alabor, Maarashana, afin de se racheter une image et sait négocier avec Sil’Elaith quand il le faut."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p56-mary-shanasti","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Mary Shanasti","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Underwater Nation","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Mary Shanasti","identity_keys":["Mary Shanasti","Ocean Queen : Mary Shanasti"],"statut":"Enders","organisation":"Underwater Nation","age":"28 ans","nationalite":"indienne"},"sections":[{"id":"antisysteme-p56-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Mary Shanasti"],["Alias / désignation","Ocean Queen : Mary Shanasti"],["Âge apparent","28 ans"],["Affiliations","Crawlers : Enders"],["Nationalité d’origine","indienne"],["Organisation","Underwater Nation"]]}]},{"id":"antisysteme-p56-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Mary Shanasti est une « enders », elle est une sorte de gourou qui possède des communautés sous￾marines indépendantes. Elle prône des principes religieux néopaganismes, elle n’a que faire des lois, puisque ses communautés sont soumises à la loi de sa propre « nation »."}]},{"id":"antisysteme-p56-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Maarashana"],["Nature réelle","demi-Aseryne, semi-daemone (Lemurianne)"],["Statut","Duchesse Suppléante"]]},{"type":"p","text":"Fille d’Alabor, cette semi-aseryne est une demi-déesse puissante, elle n’a que des aserynes et de nymphes marines dans ses communautés, elle est farouchement opposée à Seawares et tout impact corporatif alors même que les infrastructures sont construites par ces corporations cherchant à s’installer sous l’eau. Elle était l’ancienne duchesse d’amunghol mais son caractère orageux n’était pas très apprécié et finalement, Amnudya lui fut préférée. Quand elle s’énerve, elle provoque presque toujours la pluie. Les daemons de sa mère la craignent comme la peste, car elle supprime aussi instinctivement leurs pouvoirs pour se les approprier temporairement. Elle déteste les Mûliens, qu’elle trouve présomptueux et stupides mais n’a pas d’animosité pour les neo￾atlantes, en revanche, elle ne considère pas les hyperboréens comme des Aseryns."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p57-kylon-smithgerald","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kylon Smithgerald","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Underwater Nation","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Kylon Smithgerald","identity_keys":["Kylon Smithgerald","« Le marchand de sel » : Kylon Smithgerald"],"statut":"Enders","organisation":"Underwater Nation","age":"28 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p57-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kylon Smithgerald"],["Alias / désignation","« Le marchand de sel » : Kylon Smithgerald"],["Âge apparent","28 ans"],["Affiliations","crawlers : enders"],["Nationalité d’origine","Américaine"],["Organisation","Underwater Nation"]]}]},{"id":"antisysteme-p57-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Kylon Smithgerald est un combattant de l’underwater nation. Il a fait la fin de la guerre de 22-28, mais n’a pas trouvé sa place jusqu’àce qu’il ne découvre la cause des Enders réclamant les cités sous￾marines. Dans la sécurité de Seaware quand il rencontra Mary Shanasti, il préféra la suivre et trahir ses officiers que lutter."}]},{"id":"antisysteme-p57-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Tritorson"],["Nature réelle","nymphe (triton)"],["Statut","Combattant"]]},{"type":"p","text":"Les tritons sont les « nymphes » mâles aquatique, néréides, naïades et autres, ils ne sont pas moins puissants mais ont une rareté et une importance moindre chez les nymphes qui préfèrent les dieux et les humains pour se reproduire. C’est pour ça que tous les tritons s’appellent « triton +un suffixe », c’est une marque de leur statut inférieur et ne pas avoir de vrai prénom une obligation, certains s’y sont risqués mais ont assez vite mal fini. Un prénom a du pouvoir chez les nymphes, il doit vouloir dire quelque chose, les tritons qui en ont pris un n’étaient pas prêts, ils se sont dénaturés et ont été éliminés. Tritorson est un des guerriers d’Amphitrite qu’elle laisse à Maarashana. Il a du mal avec ses amours, c’est un type assez superficiel et creux quand il ne bosse pas, peu d’hommes le tolèrent à la longue."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p57-ryan-oakson","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ryan Oakson","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Underwater Nation","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Ryan Oakson","identity_keys":["Ryan Oakson","“Deep lord” : Ryan Oakson"],"statut":"Enders","organisation":"Underwater Nation","age":"50 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p57-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ryan Oakson"],["Alias / désignation","“Deep lord” : Ryan Oakson"],["Âge apparent","50 ans"],["Affiliations","crawler : Enders"],["Nationalité d’origine","Américaine"],["Organisation","Underwater Nation"]]}]},{"id":"antisysteme-p57-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ryan est un défenseur des cités sous-marines, pour lui, bien que les humains ne soient pas faits pour vivre dans les fonds marins, il est évident que l’Humanité va disparaitre de la surface émergée, elle ne pourra renaitre qu’à partir des colonies extrêmes comme celles sous l’eau ou dans l’espace. Fanatique de Mary Shanasti, c’est un des plus puissant et sanguinaires enders la suivant."}]},{"id":"antisysteme-p57-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Naasif el-Rehman"],["Nature réelle","Vampires (alghul)"],["Âge réel / complément","????"],["Statut","Combattant"]]},{"type":"p","text":"Naasif était un janissaire, il fut vampirisé en 1625, sur un champ de bataille méconnu de la guerre ottomano-persane (1623-1639), par une des filles du sultan Mehmed III (plusieurs sultans lui avaient succédé dans un bref délai). « Chevalier » de l’Alghul, Naasif n’aime pas vraiment le caractère diplomate de sa faction vampirique alors la reine lui confia souvent des tâches de protection et de conquête. En 2035, il défend les cités sous-marines, juste assez profondes pour que sans l’Hologramme les vampires n'y vivent sans jamais craindre le jour. Il sait que Mary Shanasti n’est pas forcément humaine mais ne s’imagine pas que l’underwaternation est aussi fortement considérée par les aseryns, les nymphes, les daemons et les vampires."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p58-kassidy-haynes","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kassidy Haynes","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Gold Cow Kingdom","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Kassidy Haynes","identity_keys":["Kassidy Haynes","Black cow : Kassidy Haynes"],"statut":"Enders","organisation":"Gold Cow Kingdom","age":"39 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p58-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kassidy Haynes"],["Alias / désignation","Black cow : Kassidy Haynes"],["Âge apparent","39 ans"],["Affiliations","crawlers : Enders"],["Nationalité d’origine","Américaine"],["Organisation","Gold Cow Kingdom"]]}]},{"id":"antisysteme-p58-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Kassidy est une fermière de la communauté « gold cows ». Ex-capitaine dans l’US. Marines corp, Kasssidy était une dure à cuir ayant vécu l’essentiel de sa vie le crâne rasé, poitrine bandée pour faire le plus badass possible. C’était une brute assez militariste qui prit le conflit de 22-28 avec engouement, allant « enfin » péter la sale Corée du Nord une bonne fois pour toute. Si en 28 l’issue de cette guerre lui donna raison, le prix à payer était trop lourd et ses jeunes années à prôner capitaliste exacerbé et soutenir des républicains extrêmes lui firent mal en voyant le devenir des Etats-Unis et l’essor des corporations toutes puissantes. Quand le gouverneur George Jewelson, du Kansas, vendit 60% de Topeka (capitale du Kansas) à Arcanet, Kassy et un groupe de vétérans et massacrèrent ce gouverneur et tous les corporatistes possibles. Elle prit lafuite et laissa pousser ses cheveux en joignant la communauté de Goldcows pour se cacher. Meneuse de clan, elle s’est réfugiée chez Diana pour échapper aux représailles."}]},{"id":"antisysteme-p58-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","Loup-garous (pelages dorés)"],["Âge réel / complément","???"],["Statut","Gouverneuse Ouest"]]},{"type":"p","text":"C’est un garou puissant qui apprécie néanmoins la vie de fermière."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p58-diana-buck","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Diana Buck","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Gold Cow Kingdom","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Diana Buck","identity_keys":["Diana Buck","Cow Empress : Diana Buck"],"statut":"Enders","organisation":"Gold Cow Kingdom","age":"22 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p58-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Diana Buck"],["Alias / désignation","Cow Empress : Diana Buck"],["Âge apparent","22 ans"],["Affiliations","crawlers : Enders"],["Nationalité d’origine","Américaine"],["Organisation","Gold Cow Kingdom"]]}]},{"id":"antisysteme-p58-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Diana Buck est une fermière de Californie. Elle possède le grand village agricole de « Gold cow kingdom», même si les centaines de fermiers locaux sont des survivalistes indépendants, résistant aux assauts des bikers et des mercenaires, ils survivent par les fonds donnés par Dwarfood corporation, offrant du lait, de la viande et des œufs classiques à la corporation, sans aucune norme d’hygiène ou de sécurité à suivre étant indépendants, la corporation les utilisant en soutien, n’ayant donc pas besoin d’eux dans l’absolu mais entretenant la communauté pour avoir une production inconnue des autres corporations alimentaires susceptibles d’attaquer les fermes industrielles pour mettre à genoux Dwarfood. Bien qu’elle soit jeune, Diana est une femme au fort caractère."}]},{"id":"antisysteme-p58-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","Loups-garous"],["Statut","Meneuse de clan"],["Grand meneur","Kadriye"],["Pouvoir du sang","sang Enragé"]]},{"type":"p","text":"Meneuse de son clan, elle ne laisse rien passer quand on attaque son village de garous, de latents et leurs familles. Malgré ses airs de fermière à grosse poitrine, c’est une maitresse du sang enragé, capable de combattre comme un berserker jusqu’au dernier souffle et même de forcer l’éveil des siens par sa seule rage."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p59-ethan-sheppard","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ethan Sheppard","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Gold Cow Kingdom","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Ethan Sheppard","identity_keys":["Ethan Sheppard","Grey Beef : Ethan Sheppard"],"statut":"Gouverneur du sud","organisation":"Gold Cow Kingdom","age":"54 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p59-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ethan Sheppard"],["Alias / désignation","Grey Beef : Ethan Sheppard"],["Âge apparent","54 ans"],["Affiliations","crawlers : Enders"],["Nationalité d’origine","Américaine"],["Organisation","Gold Cow Kingdom"],["Statut","Gouverneur du sud"],["Nature","humaine"]]}]},{"id":"antisysteme-p59-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ethan Sheppard était un sénateur Californien pendant la guerre, après une prestigieuse carrière dans le droit puis dans la politique, ce démocrate était aussi respecté que charismatique."}]},{"id":"antisysteme-p59-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"p","text":"Souffrant d’une forte addiction aux drogues et régulièrement corrompu, il divorça en 2027, sa femme le quittant en pointant du doigt ses additions. Sa carrière politique était au ralenti vu l’état des Etats-Unis, en attente d’un procès qui ne vint jamais, il fit pression sur le gouverneur Californien et les juges mais tomba sur Connor K. McDougals, qui, non seulement ne se laissa pas impressionné mais utilisa des lois sur les narcotrafiquant et la trahison d’état pour l’envoyer en prison, le sénateur réussissant à avoir l’emprisonnement à vie pour haute trahison au lieu de sa condamnation pour détention, usage et recèle de produits illicites. Finalement, il trouva un terrain d’entente pour repousser la décision et se planqua dans la communauté d’Enders de Goldcows. La vie de fermier lui va bien plus qu’il n’aurait imaginé, s’il conserve de fortes relations avec les politiques encore en place, il reste le « gouverneur du sud » de l’exploitation agricole. Il a trois épouses et 16 enfants depuis les quelques huit années dans la communauté et se plait à jouer les sages."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p59-jett-burris","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Jett Burris","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Gold Cow Kingdom","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Jett Burris","identity_keys":["Jett Burris","Black bull : Jett Burris"],"statut":"chef de la sécurité","organisation":"Gold Cow Kingdom","age":"","nationalite":"américaine"},"sections":[{"id":"antisysteme-p59-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Jett Burris"],["Alias / désignation","Black bull : Jett Burris"],["Affiliations","crawler : Enders/ chasseurs"],["Nationalité d’origine","américaine"],["Organisation","Gold Cow Kingdom"],["Statut","chef de la sécurité"],["Nature","humaine"]]}]},{"id":"antisysteme-p59-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Jett Burris est un ancien policier du Texas. Fantasmant les cowboys depuis l’enfance, il toujours arboré un chapeau noir digne de sens héros. La vie de policier ne l’a jamais autant passionné qu’il ne l’imaginait quand il a choisi cette carrière, s’ennuyant il lâcha son poste lors de la grande conscription générale pour la guerre de 22-28, cependant, il attendit 2026 avant que sa demande ne soit acceptée, ironiquement, si les Etats-Unis manquaient de volontaires, les états préféraient ne pas céder tous leurs policiers, pompiers et autres agents publiques utiles à la stabilité. Là encore, il ne fut pas spécialement séduit par l’horreur de la guerre même la fin de guerre, rentrant avec un gout amer en bouche. L’essor des corporations, le bond technologique et l’âge sombre des bikers lui donnèrent toutefois une envie de fuite. Volant un cheval, il erra comme le cowboy hollywoodien qu’il rêvait d’être avant de trouver « Gold Cow kingdom ». Au début rejeté, il gagna sa place en défendant les lieux face à des motards venus piller. Diana accepta qu’il ne gère la sécurité, mais lui refusa le titre de shérif tant désiré. Il fume beaucoup de N-sta même s’il est peu augmenté, pour le style. Son colt est personnalisé, c’est une arme à projectiles microplasma, il l’a ramené de Corée du Nord dont il a fait changer l’apparence externe."}]},{"id":"antisysteme-p59-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","39 ans », ????"]]}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p60-niichad-tenford","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Niichad Tenford","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","True Nations","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Niichad Tenford","identity_keys":["Niichad Tenford","« Navajobliterator » : Niichaad Tenford"],"statut":"Enders","organisation":"True Nations","age":"44 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p60-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Niichad Tenford"],["Alias / désignation","« Navajobliterator » : Niichaad Tenford"],["Âge apparent","44 ans"],["Affiliations","crawlers : mercs/ enders"],["Nationalité d’origine","Américaine"],["Organisation","True Nations"]]}]},{"id":"antisysteme-p60-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Niichaad est un descendant des Abenaquis, une première nation du nord des Etats-Unis. Jeune, il était un sportif professionnel dans le tir sportif et la lutte, mais à cause d’un fort racisme, il n’a pas été sélectionné pour les Jeux olympiques et comme il contestait la décision, des néonazis lui brisèrent les deux bras."}]},{"id":"antisysteme-p60-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Ask-we-da-eed"],["Nature réelle","nymphe (feu follet)"],["Âge réel / complément","???"],["Statut","combattant libre"]]},{"type":"p","text":"Par la suite il se constitua chasseur de prime. Après la guerre de 22-28, il fut engagé par « Nana » pour être son principal atout guerrier, se révélant avoir été un des nombreux héros très décorés à revenir, pas autant que les grandes héroïnes (Siobhain, Leslie, Makana, Veronica, Tokala, Farah, Dina et Catalina) mais comptant dans les « 200 vétérans du sang », dont A-man est le plus connus, trop souvent érigé au même niveau que les grandes héroïnes. Ask-we-da-eed est une nymphe de type lampade, un feu-follet puisqu’il est un mâle mais loin d’être une petite créature faible, c’est une incarnation des comètes et des météores, des incendies et des cratères d’impacts. Comme beaucoup de feu-follet il est fou de Belial mais n’est pas un daemon. Il surveille les vampires de « true Nations ». Il est plus puissant que moloch, on le surnomme « le seigneur météore »."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p60-nana-nandoa","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Nana  Nandoa","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","True Nations","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Nana  Nandoa","identity_keys":["Nana  Nandoa","« Nana » Nandoa","Merciless Nana: Nandoa"],"statut":"Enders","organisation":"True Nations","age":"50 ans","nationalite":"Américaine (Cheyenne)"},"sections":[{"id":"antisysteme-p60-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Nana  Nandoa"],["Alias / désignation","Merciless Nana: Nandoa"],["Âge apparent","50 ans"],["Affiliations","crawlers : Endrunners"],["Nationalité d’origine","Américaine (Cheyenne)"],["Organisation","True Nations"]]}]},{"id":"antisysteme-p60-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Nana est une grande figure de l’insurrection native américaine, Elle fut surtout connue à partie de 2026, quand l’économie américaine commença à s’affaisser, réclamant plus de pouvoirs aux natifs, plus de compensations financières face à leur génocide non reconnu. Lorsque Tokala fonda la grande réserve, elle s’y opposa par des attaques terroristes, mais sans se rattacher au « front des crocs » que menait Talatuwa, une autre figure insurgée."}]},{"id":"antisysteme-p60-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Skenandoa"],["Nature réelle","vampire"],["Âge réel / complément","8 000 ans"],["Statut","« Ehecatl »"],["Maison vampirique","«Skayenne »"]]},{"type":"p","text":"C’est un ancien vampire né de Quetzalccoatl et d’une femelle vampire d’Amérique du Nord. C’est la plus ancienne née du Roi divin vampirique et elle estime ses pouvoirs égaux à ceux d’une Megda ou d’un Dragoy. Elle est extrêmement intransigeante envers sa maison, exigeant de tuer un advervsaire puissant pour l’intégrer. Contrairement à son homologue garou, Talatuwa, elle se fout totalement des natifs américains en vérité, la cause qu’elle défend n’est qu’une hypocrisie qui l’amuse."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p61-lyric-harvey","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Lyric Harvey","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","True Nations","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Lyric Harvey","identity_keys":["Lyric Harvey","Crazy witch&bitch : Lyric Harvey"],"statut":"Enders","organisation":"True Nations","age":"68 ans","nationalite":"Américaine (comanche)"},"sections":[{"id":"antisysteme-p61-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Lyric Harvey"],["Alias / désignation","Crazy witch&bitch : Lyric Harvey"],["Âge apparent","68 ans"],["Affiliations","crawlers : Enders"],["Nationalité d’origine","Américaine (comanche)"],["Organisation","True Nations"]]}]},{"id":"antisysteme-p61-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Lyric est une comanche ayant étudié l’économie et le commerce dans une prestigieuse université. Après ses études, elle a été directrice commerciale dans une grande enseigne du domaine textile et vestimentaire. Pendant la grande crise économique elle a perdu la boite qu’elle tentait de lancer et a été rattrapée par des dettes, elle a préféré se cacher dans une réserve indienne pour fuir la justice américaine et a été oubliée pendant la guerre. Elle a intégré True Nations pour contester l’hégémonie totale de la tala corporation, s’avérant très jalouse de la réussite de Tokala."}]},{"id":"antisysteme-p61-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","mage"],["Âge réel / complément","1479 ans"],["Statut","combattante libre"],["Magie familiale","la greffe totale"]]},{"type":"p","text":"Lyric est un mage, rejetée de la loge de sa réserve, c’est une skinwalker, elle peut greffer des parties d’elle-même dans d’autres corps et inversement jusqu’à pouvoir prendre un autre corps en transférant ses cellules du cerveau. Le processus est douloureux et irréversible sur le cerveau, pour les autres organes, elle peut inverser la magie. Elle a oublié son nom d’origine et est détestée par les autres mages. Même en changeant de corps, elle garde son mageius, si elle prend un corps de mage, même si elle rend l’âme à un autre corps, le mageius de l’autre mage s’échappe lors de l’échange, mais elle reçoit une grande quantité de savoirs. C’est une nymphomane prédatrice qui adore les jeunes, hommes et femmes."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p61-kono-mc-larson","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kono Mc Larson","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","True Nations","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Kono Mc Larson","identity_keys":["Kono Mc Larson","Bloody slave : Kono McLarson"],"statut":"Enders","organisation":"True Nations","age":"","nationalite":"américaine"},"sections":[{"id":"antisysteme-p61-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kono Mc Larson"],["Alias / désignation","Bloody slave : Kono McLarson"],["Affiliations","crawler : Enders"],["Nationalité d’origine","américaine"],["Organisation","True Nations"]]}]},{"id":"antisysteme-p61-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"kono est un jeune paumé, fanatique de « nana », il boit ses paroles depuis toujours et déteste Tokala et Talatuwa comme personne bien qu’il n’en comprenne pas totalement les raisons, son caractère partisan et extrême le rend incapable de réfléchir et tempérer cette haine terrible."}]},{"id":"antisysteme-p61-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Hunbaut (table ronde)"],["Nature réelle","semi-humain (dhampire)"],["Âge réel / complément","20 ans », ????"],["Statut","combattant libre"]]},{"type":"p","text":"Kono est un serviteur des vampires. Il a été conçu pour servir sa maitresse, Skenandoa, sa mère. Son père était un simple humain esclave, il a vu sa nourrice être dévorée par Skenandoa, afin de l’éduquer. Les vampires de Quetzalcoatl n’apprécient pas les dhampires, mais la fille du roi fait exception, elle a toujours gardé ses engeances pour en faire des esclaves sacrifiables. il possède peu de dons vampiriques, presque aucun tant qu’il ne boit pas de sang, en revanche c’est un « catalyseur », c’est-à-dire qu’une fois qu’il les a activés, ils s’amplifient sans limite un bref temps, lui￾même amplifiant les dons des vampires alentours. c’est aussi un « chasseur de la table ronde », bien qu’il l’ignore, « Hunbaut » même si ce n’est vraiment pas un nom très connu. « Keu » l’a repéré et donné une épée mais kono ‘n’est pas encore venu à « Arthur »."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p62-shaynida-kean","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Shaynida kean","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Green Fairy Daughters","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Shaynida kean","identity_keys":["Shaynida kean","Second Fairy : Shaynida Kean"],"statut":"Enders","organisation":"Green Fairy Daughters","age":"36 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p62-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Shaynida kean"],["Alias / désignation","Second Fairy : Shaynida Kean"],["Âge apparent","36 ans"],["Affiliations","crawlers : enders"],["Nationalité d’origine","Américaine"],["Organisation","Green Fairy Daughters"]]}]},{"id":"antisysteme-p62-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Shaynida est une ancienne militaire. On sait peu de choses sur elle hormis qu’elle n’est pas spécialement douée ni valorisée par ses supérieurs. Elle était de l’US. Army, elle a fait ses classes avec Veronica Silver, été affecté au même groupe de combat maistrès vite a vu la blonde surpasser la masse quand elle-même peinait à se faire respecter. Elle a toujours été considérée comme chanceuse, assez belle, assez athlétique sans trop s’entrainer, pas très intelligente mais pas débile, c’est sa chance qui aurait autorisé Shaynida à survivre à la guerre de 22-28. Après la guerre, elle a été engagée par une corporation chimique et a été capturé par des activistes écologistes, elle est restée captive et est devenue un membre d’importance par hasard. Le hasard ? aucun."}]},{"id":"antisysteme-p62-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Ida"],["Nature réelle","nymphes (meliade)"],["Âge réel / complément","???"],["Statut","bras gauche d’Alayna Daewynn"]]},{"type":"p","text":"Fille de Gaïa cette nymphe qu’on décrit comme tutrice de Zeus dans les légendes est une pacifiste convaincue, elle est redoutable au combat mais elle déteste le conflit, la pollution et la dégradation des biens comme des esprits. Elle tient Alayna par chantage, l’elfe étant forcée de lui obéir pour que les GFD servent aussi les intérêts des nymphes, pas que des elfes."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p62-kelly-rinaldi","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kelly Rinaldi","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Green Fairy Daughters","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Kelly Rinaldi","identity_keys":["Kelly Rinaldi","First fairy : Kelly Rinaldi"],"statut":"Enders","organisation":"Green Fairy Daughters","age":"26 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p62-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kelly Rinaldi"],["Alias / désignation","First fairy : Kelly Rinaldi"],["Âge apparent","26 ans"],["Affiliations","Crawlers : Enders"],["Nationalité d’origine","américaine"],["Organisation","Green Fairy Daughters"]]}]},{"id":"antisysteme-p62-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Kelly était une guide forestière, elle a passé toute sa vie en forêt, ou à étudier la faune et la flore, elle voulait obtenir un doctorat en biologie appliquée, mais le caractère trop théorique de la discipline ne lui allait pas, elle n’a jamais rendu son mémoire et séchait 75% du temps pour faire de la randonnée à la place. Elle a naturellement rejoint le mouvement « GFM » mais à la division entre Alayna et Sahamena elle a préféré la vision de la première et s’est jointe à la communauté associée. Les GFM et les GFD ne sont qu’une seule et même faction, la principale nuance étant leurs méthodes, Sahamena milite dans la société californienne, Alayna refuse cette société."}]},{"id":"antisysteme-p62-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Kelinee Taleri"],["Nature réelle","elfe"],["Statut","bras-droit d’Alayna Daewynn"]]},{"type":"p","text":"Kelinee porte fièrement le prénom de la reine elfique forestière, du moins celle qui régnait quand elle quitta Aèr. C’est une elfe sylvaine pure souche et malgré son air jeune, elle est peut-être une tante ou grande tente de Titania. Elle ne dément jamais la rumeur qui ferait d’elle la reine Kelinee et la mère de Titania qu’elle aurait eu avec le prince noir Vilkerith Scytheri, engeance dépravée d’Aleyera, mais les elfes anciens trouvent honteux que cela l’amuse autant d’entretenir un tel mensonge. Elle-même reste une chasseuse et une forestière hors-pair ayant. Elle déteste la Chasse Fantastique et les corporations."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p63-sim-hyun-ki","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Sim Hyun-Ki","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Green Fairy Daughters","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Sim Hyun-Ki","identity_keys":["Sim Hyun-Ki","Kim-jong-bull : Sim Hyun-Ki"],"statut":"Enders","organisation":"Green Fairy Daughters","age":"40 ans","nationalite":"Coréenne (nord)"},"sections":[{"id":"antisysteme-p63-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Sim Hyun-Ki"],["Alias / désignation","Kim-jong-bull : Sim Hyun-Ki"],["Âge apparent","40 ans"],["Affiliations","crawlers : enders"],["Nationalité d’origine","Coréenne (nord)"],["Organisation","Green Fairy Daughters"]]}]},{"id":"antisysteme-p63-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Tous les nords-coréens ne sont pas des terroristes cherchant à restaurer la gloire de la Corée unifiée ou à se venger de la défaite injuste qu’ils ont vécu. Certains ont un réel besoin de rédemption, ils sont même plus nombreux que les autres, Hyun-Ki en fait partie. Incapable de s’intégrer par son passé et son origine, il était condamné à mort après s’être rendu aux autorités Californienne, le gouvernement Page et celui des Etats-Unis entrant en conflit sur son cas. Libéré par des terroristes, il a préféré trouver la communauté des GFD et cherche à réparer les fautes de son pays en défendant des innocents."}]},{"id":"antisysteme-p63-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Ki-0II-49-siu"],["Nature réelle","Talass"],["Statut","garde du sapin"]]},{"type":"p","text":"Tous les Talass de l’émeraude sanglante ne sont pas des psychopathes assoiffés de sang, entrainés, belliqueux et vifs, ils restent des Talass avant tout et moins ils sont modifiés plus ils sont «Talass ». Ki-49 n’a rien compris à la guerre de 22-28, tout était confus et malsain pour lui, sa logique ultrarationnelle n’a jamais déterminé de cohérence dans les actions nord-coréennes. Il n’a pas trahi pour autant mais dès qu’il est arrivé aux Etats-Unis il a contacté le GAAC. Le GAAC l’a fait emprisonner, alors une fois libéré, il s’est caché. Pour lui, l’ennemi véritable est le REPTILE et les altérations climatiques, rien d’autre."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p63-huxley-kane","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Huxley Kane","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Green Fairy Daughters","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Huxley Kane","identity_keys":["Huxley Kane","The Alaskan : Huxley Kane"],"statut":"Enders","organisation":"Green Fairy Daughters","age":"","nationalite":"américaine"},"sections":[{"id":"antisysteme-p63-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Huxley Kane"],["Alias / désignation","The Alaskan : Huxley Kane"],["Affiliations","crawler : Ender"],["Nationalité d’origine","américaine"],["Organisation","Green Fairy Daughters"]]}]},{"id":"antisysteme-p63-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Huxley n’est pas le genre de type qu’on imaginerait dans la communauté des GFD. Sociable et serviable, il adore les gens et cet ancien enseignant ne se repose jamais. Né en Alaska, dans un petit village, il a fait son début de vie à Anchorage où il bossait dans une scierie puis comme bûcheron, il a aussi travaillé dans une exploitation minière et une concession de chercheur d’or. Il a commencé à travailler à 15 ans, alors à 17 ans, au début de la guerre, il ne comprit pas qu’on ne l’engage pas.Il pu s’engager à 22 ans, en 2027, pour la fin de la guerre même s’il resta dans les troupes de logistique de l’US . Army. Après la guerre, il s’exila au sein des GFD, traumatisé par avoir été amené à tuer des gens malgré tout pendant la dernière bataille."}]},{"id":"antisysteme-p63-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","humain (corrompu)"],["Âge réel / complément","30 ans », ????"],["Statut","garde de l’épicéa"]]},{"type":"p","text":"Fils rejeté de Miluska VOROSHILOV fertilisée par le « roi du givre » dans ses rêves, il n’est ni fléau ni mage mais il sent en lui de sombres pulsions et une grande faim. Ce qui l’a traumatisé pendant la guerre c’est qu’il sentit sa force physique augmenter en proportion de son envie de manger les ennemis. Il sent qu’il est un « roi du bois au fond de lui mais préfère s’isoler. Parfois il avale des petits animaux crus."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p64-jane-moreno","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Jane Moreno","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Green Nomads","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Jane Moreno","identity_keys":["Jane Moreno","Dragon punch : Jane Moreno"],"statut":"Enders","organisation":"Green Nomads","age":"47 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p64-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Jane Moreno"],["Alias / désignation","Dragon punch : Jane Moreno"],["Âge apparent","47 ans"],["Affiliations","Crawlers : enders/gunrunners"],["Nationalité d’origine","Américaine"],["Organisation","Green Nomads"],["Sous-faction","Chef des Faucons Malachites"]]}]},{"id":"antisysteme-p64-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Un village mobile de caravanes et de camions traverse les Etats-Unis, doté de véhicules blindés sur les flancs et de véhicules lourdement armés dans le convoi, ces Enders sont les « green Nomads », un peu rattachés aux motards, un peu rattachés à la mafia Irlandaise, les cartels mexicains, il s’agit de familles armées se déplaçant en groupe. Jane Moreno est à la tête du grand convoi. Solitaire et badass, c’est une meneuse qui n’apprécie pas vraiment la technologie, elle ne préserve que les armes les plus simples et robustes, rien de connecté."}]},{"id":"antisysteme-p64-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Gadyndra"],["Nature réelle","dragonne (Nareysvor)"]]},{"type":"p","text":"Dragonne jaune, elle a longtemps été l’alliée d’Aleyna Daewynn, avant de finalement la virer. Bien qu’indépendante, la dragonne considère les « faucon malachite » comme ses œufs en quelque sorte et bien que pas vraiment maternelle ni douce, elle est extrêmement possessive et ne laissera plus personne les diriger à part elle-même. Elle n’est pas démente ni idiote cela étant dit, quand les chefs de sous￾faction de la Fédération se rassemblent, elle en est et prend son second, afin qu’il traduise si jamais les elfes parlaient entre eux dans leur langue ancienne."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p64-jayceon-osborn","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Jayceon Osborn","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Green Nomads","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Jayceon Osborn","identity_keys":["Jayceon Osborn","Big Jay driver : Jayceon Osborn"],"statut":"Enders","organisation":"Green Nomads","age":"23 ans","nationalite":"américaines"},"sections":[{"id":"antisysteme-p64-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Jayceon Osborn"],["Alias / désignation","Big Jay driver : Jayceon Osborn"],["Âge apparent","23 ans"],["Affiliations","crawlers : enders"],["Nationalité d’origine","américaines"],["Organisation","Green Nomads"],["Sous-faction","Sous-Chef des Faucons Malachites"]]}]},{"id":"antisysteme-p64-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Il était le principal opposant à Alayna dans la communauté nomade, plus jeune et plus agressif, il voulait toujours plus d’actes et moins de réflexions. Malgré leur opposition elle lui sauva la vie des centaines de fois. Finalement, quand Jane renversa Alayna, il se retrouva à devoir choisir entre ses ambitions et se soumettre. Il ne fit pas le fier face à l’ancien sous-chef de la communauté. Pilote d’un char très modifié, c’est le principal défenseur de l’aile droite du convoi quand la communauté bouge. La vitesse de son véhicule a tendance à surprendre, puisqu’il peut rattraper les motos les plus usuelles aisément et couper par un terrain accidenté pour rattraper les plus rapides. « Big jay » est le surnom du char."}]},{"id":"antisysteme-p64-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Jacyr Oceriol"],["Nature réelle","elfes"]]},{"type":"p","text":"En tant qu’elfe, il n’a pas grand-chose de plus à savoir sur lui, il libéra une chaine de v’aagor il y a 3 siècles et pour le punir, il porte un tatouage d chaine dans le dos, entouré de coups de fouets. C’était une erreur, un de ses amants, Frildec, se joua de lui pour le mener à cette erreur."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p65-meaton-miles","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Meaton Miles","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Green Nomads","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Meaton Miles","identity_keys":["Meaton Miles","Morgax the butcher : Meaton Miles"],"statut":"Enders","organisation":"Green Nomads","age":"28 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p65-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Meaton Miles"],["Alias / désignation","Morgax the butcher : Meaton Miles"],["Âge apparent","28 ans"],["Affiliations","crawlers : enders"],["Nationalité d’origine","Américaine"],["Organisation","Green Nomads"]]}]},{"id":"antisysteme-p65-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Parfois les apparences sont trompeuses, Meaton mesure 2.74 m, près de 250 kg, il a un regard plus proche de celui d’un ours ou d’un rhinocéros et grince souvent des dents et il a le titre d’expert en diplomatie, c’est le négociateur que Jane utilise tout le temps et son ratio de réussite est assez élevé. Parfois, les apparences sont trompeuses… mais pas le concernant. Ou plutôt, s’il a l’air d’être une brute, il se révèle en être une encore plus sauvage et stupide qu’on ne pourrait le craindre, tel un cliché vivait, il parle très peu et charge à vue tout ce qu’on lui désigne comme voulant « négocier »."}]},{"id":"antisysteme-p65-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","thulkar (orc)"],["Statut","expert négociateur en diplomatie"]]},{"type":"p","text":"C’est un orc, à la base il n’avait rien à foutre des faucons de malachite, il voulait juste défier Alayna, mais Jane avait déjà dégagé l’elfe, l’orc brave défia la dragonne et se fit écraser d’un coup de queue, elle l’adopta, lui grava un œuf sur le dos et le nomma négociateur, puisqu’il aimait se battre. Il n’apprécie pas d’être considéré comme un chien d’attaque par la dragonne et ses elfes, mais pour être libre il doit vaincre un dragon or, ils sont assez peu nombreux, voire extrêmement rares et les rares qui sont connus sont puissants, souvent plus que Jane, qu’il n’arrive déjà pas à battre."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p65-leena-merry","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Leena Merry","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Green Nomads","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Leena Merry","identity_keys":["Leena Merry","Orange Lee : Leena Merry"],"statut":"Enders","organisation":"Green Nomads","age":"","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p65-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Leena Merry"],["Alias / désignation","Orange Lee : Leena Merry"],["Affiliations","crawler : enders"],["Nationalité d’origine","Américaine"],["Organisation","Green Nomads"]]}]},{"id":"antisysteme-p65-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Leena est la capitaine de la « cavalerie » des « green Nomads », elle possède donc le commandement d’une centaine de camions blindés, d’une douzaine de chars lourds et d’un millier de motards. La « Cavalerie » est l’élite des Greenomads, meilleures armes, meilleure nourriture, meilleurs traitements, meilleure hygiène aussi, meilleure discipline également malgré des apparences de barbares sanguinaires punk de post-apo des années 80."}]},{"id":"antisysteme-p65-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","El’Ynn Manaril"],["Nature réelle","elfe"],["Âge réel / complément","30 ans », ????"],["Statut","capitaine de la « cavalerie »"]]},{"type":"p","text":"Leena est une elfe, El’Ynna de son vrai nom. Membre des faucons de malachite, elle descend des plus rares elfes du désert sur Aèr, c’est pourquoi les Green nomads lui correspondent tant. Elle est née sur Terre avant l’Hologramme. Son « père » était un humain qui la trouva après un pillage d’une oasis, elle n’était qu’une enfant et tant ses oreilles que ses cheveux d’un rouge orangeait la différenciait des humains locaux. Amkhu, la nomma Linsekh-ra bien qu’elle connût déjà son nom elfique. Elle ‘n’apprécie pas trop le despotisme de Jane sur les greenomads, essentiellement des elfes et lui tient souvent tête."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p66-grace-drusilla-mannan","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Grace Drusilla Mannan","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Fermes Mannan","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Grace Drusilla Mannan","identity_keys":["Grace Drusilla Mannan","Wild Grace : Grace Mannan"],"statut":"Enders","organisation":"Fermes Mannan","age":"22 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p66-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Grace Drusilla Mannan"],["Alias / désignation","Wild Grace : Grace Mannan"],["Âge apparent","22 ans"],["Affiliations","crawlers : enders"],["Nationalité d’origine","Américaine"],["Organisation","Fermes Mannan"]]}]},{"id":"antisysteme-p66-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ainée d’Harmony, Grace est une jeune femme extrêmement volontaire. Assez rude et campagnarde, elle n’a rien à faire de la société moderne, elle se voit comme un cowboy et ne se laisse jamais faire. Elle est assez sportive et audacieuse mais elle cache une personnalité abimée, le regard de sa mère lui importe infiniment, et elle se sent éternellement jugée et inférieure aux attentes de cette dernière. Malgré sa rudesse c’est donc une femme plutôt fragile qui préférera taper que s’ouvrir aux autres."}]},{"id":"antisysteme-p66-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","demi-humaine (nephilim)"],["Âge réel / complément","???"],["Statut","Cowgirl Mannan"]]},{"type":"p","text":"Nephilim de l’Archange Manakielle, elle en possède de grands pouvoirs puisqu’elle peut annuler notamment ceux des angelus simples, surtout ceux de Gabrielle. Elle fait un peu chasseuse dans la communauté et fait aussi figure de shérif."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p66-harmony-melinda-mannan","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Harmony Melinda Mannan","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Fermes Mannan","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Harmony Melinda Mannan","identity_keys":["Harmony Melinda Mannan","Harmony’s Angel : Harmony Mannan"],"statut":"Enders","organisation":"Fermes Mannan","age":"46 ans","nationalite":"américaine"},"sections":[{"id":"antisysteme-p66-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Harmony Melinda Mannan"],["Alias / désignation","Harmony’s Angel : Harmony Mannan"],["Âge apparent","46 ans"],["Affiliations","crawler : enders"],["Nationalité d’origine","américaine"],["Organisation","Fermes Mannan"]]}]},{"id":"antisysteme-p66-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Harmony Mannan est une ender, des crawlers renonçant à la vie urbaine pour vivre en communautés ou en solitaires sans dépendre des Corporations ou des vestiges de gouvernements. Elle est à la tête de la ferme Mannan, qu’elle tient avec ses deux filles et quelques proches. Si elle ne fait pas ses presque cinquante ans ni ne semble très dangereuse dans ses robes d’été et avec son grand chapeau de paille, c’est un ancien agent de la CIA qui a vu l’influence corporative monter et a préféré s’en éloigner."}]},{"id":"antisysteme-p66-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Manakielle"],["Nature réelle","archangelus"],["Âge réel / complément","????"],["Statut","Archange renégat"],["Divinité","Elynea"],["Pouvoir principal","la connaissance"]]},{"type":"p","text":"Manakielle est l’archange de la connaissance. Elle a été considérée comme renégate car son pouvoir lui permettait de savoir presque tout sur une cible à la seconde où elle se connectait à son essence. Envieuse d’avoir toujours plus de savoirs, elle s’était un peu trop rapprochée d’Astaroth, la déesse. La véritable raison à sa déchéance et de la victoire totale de Gabrielle survint quand Manakielle s’approcha d’Ashlutum, de la secte du grand Savoir, vénérant Sharith, déjà mise de côté, l’archange fut définitivement emprisonné quand on la suspecta d’avoir cherché à avoir les « yeux d’or »."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p67-delicacy-jarah-mannan","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Delicacy Jarah Mannan","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Fermes Mannan","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Delicacy Jarah Mannan","identity_keys":["Delicacy Jarah Mannan","Powerful Delicacy : Delicacy Mannan"],"statut":"Enders","organisation":"Fermes Mannan","age":"20 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p67-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Delicacy Jarah Mannan"],["Alias / désignation","Powerful Delicacy : Delicacy Mannan"],["Âge apparent","20 ans"],["Affiliations","crawlers : Enders"],["Nationalité d’origine","Américaine"],["Organisation","Fermes Mannan"]]}]},{"id":"antisysteme-p67-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Deuxième fille d’Harmony, Delicacy est une jeune femme assez charmante et séductrice. Elle adore la ferme, les animaux et la communauté, c’est un rayon de soleil pour tous les fermiers et agriculteurs de la communauté. Elle joue et abuse de ses airs ingénus, de sa jeunesse et de ses sourire pour avoir absolument tout ce qu’elle désire, elle est adorée de sa mère, malgré un égoïsme certain qu’on ne lui soupçonne pas. En revanche, elle adore sa sœur ainée, qu’elle désespère de voir chercher à être félicité par leur génitrice."}]},{"id":"antisysteme-p67-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","demi-humaine (nephilim)"],["Statut","Cowgirl Mannan"]]},{"type":"p","text":"Nephilim de l’Archange Manakielle, elle en possède de grands pouvoirs puisqu’elle peut annuler notamment ceux des angelus simples, surtout ceux de Gabrielle. Elle possède une force physique colossale et semble tenir bien plus de l’archange que de l’humaine. Manipulatrice et menteuse, elle est aussi glaciale au fond d’elle que sa sœur ne semble humaine et fragile."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p67-ken-larry-graff","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ken Larry Graff","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Fermes Mannan","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Ken Larry Graff","identity_keys":["Ken Larry Graff","Cowboy Ken : Ken Larry Graff"],"statut":"cowboy Mannan","organisation":"Fermes Mannan","age":"","nationalite":"américain"},"sections":[{"id":"antisysteme-p67-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ken Larry Graff"],["Alias / désignation","Cowboy Ken : Ken Larry Graff"],["Affiliations","crawler : enders/ chasseurs"],["Nationalité d’origine","américain"],["Organisation","Fermes Mannan"],["Statut","cowboy Mannan"],["Nature","humaine"]]}]},{"id":"antisysteme-p67-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ken est un fils de Josh Graff, le « révérend » il a été reconnu mais n’a pas vraiment connu son père. Sa mère l’éleva dans le Kentucky, à Frankfort. Athlète accompli, ce pompier volontaire n’a jamais aimé l’école et devint vacher dès ses 16 ans. Quand il avait 21 ans, ce bellâtre entretenait deux relations, une avec le propriétaire de l’exploitation où il travaillait, Jenna, et une avec une serveuse de son dinner préféré, Stephany. Avide de conquête, il se lança dans une troisième relation avec Sophia, une sculpturale norvégienne qui ruina sa vie. En effet, elle semblait savoir déjouer le moindre mensonge et le mettait face à ses contradictions en public, une leçon d’humilité qu’il méritait mais quand elle commença à draguer Stephany et la pousser à harceler Jenna. Jenna brula l’exploitation et fut abattue par la police en menaçant de tuer sa famille, Stephany disparut et Sophia déménagea pour New-York. Ken réalisa que la norvégienne était inhumaine et s’était amusée avec lui afin de lui voler un révolver amérindien qu’il avait gagné au poker."}]},{"id":"antisysteme-p67-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","30 ans », ????"]]},{"type":"p","text":"S’approchant de chasseurs la traquant il poursuivit le vampire jusqu’à retrouver Stephany, devenue Moroï et la tuer une fois obtenu l’adresse de Sophia. Une fois tué ses deux ex, il s’isola en Californie, montant une ferme qu’ Harmony Mannan lui racheta des années après, l’engageant comme fermier."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p68-skye-bishop","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Skye Bishop","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Mola Mola","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Skye Bishop","identity_keys":["Skye Bishop","Lady Mother-of-pearl : Skye Bishop"],"statut":"Enders","organisation":"Mola Mola","age":"25 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p68-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Skye Bishop"],["Alias / désignation","Lady Mother-of-pearl : Skye Bishop"],["Âge apparent","25 ans"],["Affiliations","crawlers : Enders"],["Nationalité d’origine","Américaine"],["Organisation","Mola Mola"]]}]},{"id":"antisysteme-p68-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Skye Bishop est une « grande sœur » du Mola Mola, une des principales personnes dotées d’un peu d’autorité dans cette communauté hippie. Elle est reconnaissable à son bikini rouge et son ttouage de requin dans le dos. Derrière un sourire toujours sur le visage, c’est une des personnes les plus craintes du Mola Mola, puisqu’elle est la « Juge » de la communauté, celle qui tranche en cas de conflit, le Mola Mola n’ayant pas de lois fixes et écrites mais un jugement populaire, un comportement qui ne dérange personne n’’étant pas source d’enquête ou de sanction, au contraire, un comportement, même anodin qui dérange assez de personnes va mener à une décision de justice."}]},{"id":"antisysteme-p68-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Aesarine Atilias Zenos"],["Nature réelle","aseryne (mulienne)"],["Âge réel / complément","???"],["Statut","grande soeur"]]},{"type":"p","text":"Fille de Drasealia Zenos, une princesse bâtarde mûlienne et de Kielras Lisirast, un cousin de la duchesse atlante Illeana Lisirast, c’est une noble ayant préféré s’occuper de son cul plutôt que des affaires mûliennes, le Mola Mola lui servant de petite cour où rassembler ses aseryns mécontents."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p68-piripi-stuart-hariwana","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Piripi Stuart Hariwana","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Mola Mola","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Piripi Stuart Hariwana","identity_keys":["Piripi Stuart Hariwana","Happy hippie : Piripi"],"statut":"Enders","organisation":"Mola Mola","age":"60 ans","nationalite":"Néozélandaise"},"sections":[{"id":"antisysteme-p68-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Piripi Stuart Hariwana"],["Alias / désignation","Happy hippie : Piripi"],["Âge apparent","60 ans"],["Affiliations","crawlers (Enders)"],["Nationalité d’origine","Néozélandaise"],["Organisation","Mola Mola"]]}]},{"id":"antisysteme-p68-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Piripi dirige une vaste communauté de Enders, les survivalistes du « Mola Mola », une communauté maritime qui s’empare d’îles et de cités sous-marines pour vivre en indépendance complète du reste du monde. Ils se veulent pacifiques mais ils n’hésitent jamais à tuer toute forme d’attaque corporatiste ou gouvernementale. Piripi n’a pas pour volonté de chercher la bagarre, il préfère se détendre, surfer, jouer de la guitare, pêcher, baiser et siester en général, c’est un héritier de l’idéologie Hippie. Hélas, si on le cherche, on peut vite trouver, l’ex général de la Ngāti Tūmatauenga (la New Zealand army), vétéran de la guerre de 22-28."}]},{"id":"antisysteme-p68-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Pwirishiripi"],["Nature réelle","Baséanne hybride"],["Âge réel / complément","»"],["Statut","sous-directeur"]]},{"type":"p","text":"Baséan d’espèce, il a été recombiné avec de l’ADN thalsios tant il aimait la mer. Ce n’est pas le combattant qu’on imagine. Il reste un être assez tranquille, qui cherche surtout la détente, le plaisir et le repos. Le Mola mola a tendance à se foutre des règles, on se révèle parfois au besoin, et les gens ne paniquent pas, l’alcool, la drogue étant souvent encouragés, on met sur le dos d’hallucinations ou de la bêtise. La communauté est assez habitée par des Aseryns de Mu, c’est la première espèce non-humaine de la faction, devant les extrals qui l’ignorent. La faction extrale sert surtout de soutien logistique à l’hydroguard."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p69-nako-tereiti","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Nako Tereiti","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Mola Mola","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Nako Tereiti","identity_keys":["Nako Tereiti","Mother Na : Nako Tereiti"],"statut":"grande soeur","organisation":"Mola Mola","age":"38 ans","nationalite":"néozélandaise"},"sections":[{"id":"antisysteme-p69-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Nako Tereiti"],["Alias / désignation","Mother Na : Nako Tereiti"],["Âge apparent","38 ans"],["Affiliations","crawlers : enders"],["Nationalité d’origine","néozélandaise"],["Organisation","Mola Mola"],["Statut","grande soeur"],["Nature","humaine"]]}]},{"id":"antisysteme-p69-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Nako est une beauté de Nouvelle-Zélande, elle a grandi dans un environnement assez pauvre mais serein. Malgré ses airs de mannequin, c’est une pêcheuse et une guide touristique à la base. Pendant la guerre, elle n’a pas été enrôlée ou autre, en revanche, elle a été entrainée comme tous les adultes de Nouvelle-Zélande. En 2023, le croiseur de combat « Rim Hye » attaqua l’Australie, s’il a été coulé non sans de grands efforts de la flotte australiennes et de ses voisins, ça a marqué les esprits. L’économie néozélandaise s’est effondrée, la guerre étant bien plus proche que prévue géographiquement. Durant l’essor des corporations, cette crise économique n’a pas cessé, au contraire, menant à un exode des populations locales vers des cités sous-marines ou des îles artificielles, stations marines et autres, où l’embauche était forte. Courant 2031, Nako mena une rébellion dans la station Delta blue de Seaware, c’est ainsi, soutenue par le Mola Mola, qu’elle intégra cette faction."}]},{"id":"antisysteme-p69-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p69-pakanga-pikari","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Pakanga Pikari","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Mola Mola","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Pakanga Pikari","identity_keys":["Pakanga Pikari","The Lawyer : Pakanga Pikari"],"statut":"Enders","organisation":"Mola Mola","age":"","nationalite":"néozélandais"},"sections":[{"id":"antisysteme-p69-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Pakanga Pikari"],["Alias / désignation","The Lawyer : Pakanga Pikari"],["Affiliations","crawler : ender"],["Nationalité d’origine","néozélandais"],["Organisation","Mola Mola"]]}]},{"id":"antisysteme-p69-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Pakanga est un avocat néozélandais, du moins il l’était jusqu’à la guerre de 2022-2028 et l’attaque du croiseur coréen. Après cette date, il s’enrôla dans la Ngāti Tūmatauenga (la New Zealand army), avant de retourner à la vie civile en 2027. Après ça, il suivit le général Hariwana dans la communauté pacifique de Mola Mola, à l’origine une flotte indépendante pacifique refusant la guerre, les taxes et toute loi inutile."}]},{"id":"antisysteme-p69-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","Mage"],["Âge réel / complément","40 ans », ????"],["Statut","grand frère"],["Magie familiale","arthropodomancie"]]},{"type":"p","text":"Pakanga est le second plus puissant mage de Nouvelle-Zélande encore en vie. Il existe Rakina, à la loge insulaire, mais elle est à peine humaine, puisqu’elle est semi-dive. Pakanga est un mage possédant un mageius du genre alchimique, c’est un « arthropodomancien », c’est￾à-dire qu’il peut créer des exosquelettes animés d’insectes, arachnides ou crustacés à partir de minéraux mais aussi altérer son corps pour en prendre la forme. Il a une fâcheuse tendance à vouloir s’entourer d’Amazones plus que de mages étant donné que dans la communauté Mola mola, il est le seul vrai mage et tient les sorciers sous sa coupe aisément."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p70-saurona-maxima-drakontos","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Saurona Maxima Drakontos","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Losttown","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Saurona Maxima Drakontos","identity_keys":["Saurona Maxima Drakontos","the Maximom : Saurona Drakontos"],"statut":"Enders","organisation":"Losttown","age":"46 ans","nationalite":"égyptienne"},"sections":[{"id":"antisysteme-p70-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Saurona Maxima Drakontos"],["Alias / désignation","the Maximom : Saurona Drakontos"],["Âge apparent","46 ans"],["Affiliations","crawlers : enders / mafia de losttown"],["Nationalité d’origine","égyptienne"],["Organisation","Losttown"]]}]},{"id":"antisysteme-p70-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Saurona est la matrone d’une part de la mafia de lostown."}]},{"id":"antisysteme-p70-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Maxima"],["Nature réelle","xewenne (corrompue)"],["Âge réel / complément","???"],["Statut","matrone de la mafia"]]},{"type":"p","text":"Elle contrôle notamment la branche du « dragon des étoiles ». Elle s’entends très bien avec Ulfric, mais c’est une femme tout en charme et en séduction qui apprécie grandement nouer de nouvelles alliances, parfois au détriment d’anciennes, stables et rentables mais l’ennuyant. Malgré son caractère félin et séducteur, son corps trahi une sportive de niveau olympique, c’est une force de la nature, probablement augmentée qui peut broyer la nuque de ses amants ou amantes ayant un mot de travers dans sa chambre. Matriarche Xewenne, elle est l’amie proche des trois matriarches Mo’senne puisqu’avec elles et un vétéran femelle Chezonne, elles forment « l’alliance rouge ». Comme les mo’sennes, elle vénère Shaoggith, la « mère des espèces reptilienne », qui aurait été vaincue et jetée sur Terre il y aurait des temps immémoriaux. Impitoyable cette matriarche guerrière aime jouer de sa fausse apparence, même si à Lostown, l’Hologramme est presque inexistant. Sa mère est la génitrice de 51 des 55 xewens terriens. Elle a une confiance en elle lui interdisant de douter, quitte à avoir tort."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p70-ulfric-tamer","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ulfric Tamer","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Losttown","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Ulfric Tamer","identity_keys":["Ulfric Tamer","the Son of Tiamat : Ulfric Tamer"],"statut":"Enders","organisation":"Losttown","age":"48 ans","nationalite":"britannique"},"sections":[{"id":"antisysteme-p70-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ulfric Tamer"],["Alias / désignation","the Son of Tiamat : Ulfric Tamer"],["Âge apparent","48 ans"],["Affiliations","Crawlers : Enders"],["Nationalité d’origine","britannique"],["Organisation","Losttown"]]}]},{"id":"antisysteme-p70-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Ulfric Tamer est le « seigneur » de Lostown, il est comme un baron de cartel, un grand parrain de mafia ou bien encore un gourou de secte, il a un pouvoir quasi-absolu sur toute la ville et absolument tout le monde le craint au sein de cette cité autarcique. Les plus anarchistes détestent sa position suprême, alors il est confronté à énormément de sous-factions voulant le renverser, ce qui renforce ses mesures sanguinaires et totalitaires."}]},{"id":"antisysteme-p70-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nom de la Vérité","Rulfam"],["Nature réelle","fléau supérieur (« dragon »)"],["Statut","Seigneur de lostown"]]},{"type":"p","text":"Rulfam est une engeance de Shaoggith et de Shorolth, leur union remonte à une date ancienne, mais le fléau a créé des enfants pendant de nombreux millénaires à partir de cette semence, bien après que le fondateur dragon n’ait compris sa nature et entamé des mesures pour lutter. C’est le dernier en vie de cette lignée, le dernier dragon-fléau que l’ordre sauroctone n’a pas tué. Il a tué le plus puissant chevalier de ces chasseurs, Siegfried il y a quelques siècles, et raté de tuer celle qui l’aimait, Brunehilde. Il échoua néanmoins à retrouver l’armure de Shaoggith jusqu’à ce que Siegfried, ressuscité par magie, devenu daemon de Bélial ne la cède à sa fille, Tiamandra. Ulfric est un monstre inhumain mais il doit composer à Lostown avec des factions assez hétéroclites comme une communauté d’Aliens, une loge de mages et masse de neopunks furieux."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p71-apepia-xii-white","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Apepia XII White","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Losttown","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Apepia XII White","identity_keys":["Apepia XII White","the Snake witch : Apepia XII"],"statut":"Enders","organisation":"Losttown","age":"28 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p71-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Apepia XII White"],["Alias / désignation","the Snake witch : Apepia XII"],["Âge apparent","28 ans"],["Affiliations","crawlers : enders - mafia de losttown"],["Nationalité d’origine","Américaine"],["Organisation","Losttown"]]}]},{"id":"antisysteme-p71-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Apepia est une est la matrone d’une part de la mafia de lostown. Elle contrôle notamment la branche du « Serpent du chaos ». Elle incarne la cruauté suprême qui règne à Lostown, ayant déjà empoisonné des points d’eau pour récupérer des quartiers afin d’y stocker des denrées -dont de l’eau potable-."}]},{"id":"antisysteme-p71-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Nature réelle","mage (loge Losttown)"],["Statut","maitresse de la loge"],["Magie familiale","chaos des ténèbres"]]},{"type":"p","text":"Maitresse mage de la loge de la ville, elle est la XIIème incarnation du mage « Apep », fils de Diablo et d’un mage étant un fragment de V’aagor. Apep est capable de s’incarner, il garde ses souvenirs et son mageius dans un corps qu’il aura préparé, un corps sur deux est une femme qu’il fertilise avant de s’incarner en elle, afin que leur enfant n’hérite du maximum de dons. L’enfant est dévoré magiquement par la suite pour réintégrer la magie et les dons développés. En tant qu’Apep XI, il fut tué par un daemon de Lucifer avant de préparer un corps, se maintenant en vie par nécromancie, il vola une création de son ami, Faust, une de ses homoncules et massacra les autres à l’exception d’Aisha et de quelques prototypes, mieux cachés. Le corps d’Homoncule était puissant en magie des fléaux bien que moins compatible avec la magie familiale. Vénérant Shaoggith et v’aagor, c’est une ennemie farouche de Lucifer essentiellement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p71-zigmars-vilks","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Zigmars Vilks","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Losttown","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Zigmars Vilks","identity_keys":["Zigmars Vilks","The fallen Dragon : Zigmars Vilks"],"statut":"croquemitaine de Losttown","organisation":"Losttown","age":"","nationalite":"Lettone"},"sections":[{"id":"antisysteme-p71-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Zigmars Vilks"],["Alias / désignation","The fallen Dragon : Zigmars Vilks"],["Affiliations","crawler : enders/ chasseurs (ordre sauroctones)"],["Nationalité d’origine","Lettone"],["Organisation","Losttown"],["Statut","croquemitaine de Losttown"],["Nature","humaine (corrompu)"]]}]},{"id":"antisysteme-p71-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Zigmars est un letton né en 1985. Plein de bonne volonté et d’avenir, il souhait étudier l’astronomie quand un groupe sectaire l’arracha à ses parents, l’ordre sauroctone. Par son sang, il était un des fils cachés de Wigbeorn, un chevalier de la plus terrible lignée, les descendants de Saint George. Un jour, néanmoins, un demi-frère sorti de nulle-part se montra plus compétent encore et obtint l’armure, Zigmars se faisant marquer au fer rouge dans le dos un sceau pour corrompre son corps, qu’il ne puisse pas voler l’armure au nouveau détenteur."}]},{"id":"antisysteme-p71-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ MJ","Valeur"],["Âge réel / complément","50 ans », ????"]]},{"type":"p","text":"Entrainé 12 ans, de ses 9 ans à ses 21 ans, il donna toute son âme pour hériter de l’armure la plus terrible, « Nahfr», la peau de Tiamat, de Shaoggith en vérité. Rejeté de l’ordre sans avoir d’autre échec que d’avoir été moins bon que Siegfried, un daemon en vérité qui avait déjà été membre de l’ordre, il se voua à pleinement prier Shaoggith et dans un besoin infini de vengeance, il obtint une mue de Rulfam, le dernier dragon-fléau. Il devint un chevalier sauroctone corrompu mais n’eut pas de vengeance, Siegfried disparaissant. Déprimé, il erre à Lostown, fléau tueur de fléau, rassemblant les autres chevaliers sauroctones rejetés dans l’espoir qu’un jour le détenteur actuel de Nahr ne commette l’erreur de venir et ne soit sacrifié à la vraie déesse : Shaoggith pour que Zigmars n’en reçoive l’amour qu’elle lui aurait promis dans un songe."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-antisysteme-p72-faith-norton","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Faith Norton","source":"factions crawlers _ les anti système(3).pdf","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Anti-système","Enders","Losttown","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Faith Norton","identity_keys":["Faith Norton","God’s childen : Faith Norton"],"statut":"chef des insurgés de Lostown","organisation":"Losttown","age":"24 ans","nationalite":"Américaine"},"sections":[{"id":"antisysteme-p72-fiche","title":"Profil Crawler · Anti-système","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Faith Norton"],["Alias / désignation","God’s childen : Faith Norton"],["Âge apparent","24 ans"],["Affiliations","crawlers : enders – insurgés"],["Nationalité d’origine","Américaine"],["Organisation","Losttown"],["Statut","chef des insurgés de Lostown"],["Nature","humaine"]]}]},{"id":"antisysteme-p72-realite","title":"Informations Réalité · Anti-système","level":2,"blocks":[{"type":"p","text":"Faith est une insurgée, une terroriste s’étant réfugiée à Lostown avec son groupuscule. Elle était la fille d’une gradée de l’armée qui a essayé de dénoncer des exactions perpétrées durant la guerre et qui s’est vue privée de toute solde, toute rente et de tout droit. En 2030, elle se suicida, Faith avait 19 ans et garda une rancœur terrible contre les institutions. En 2032, elle fut identifiée dans l’attaque terroriste du métro de Los Angeles, après une longue traque, elle préféra se cacher parmi les motards où on lui indiqua une ville souterraine.Le cauchemars débuta par un lieu considéré comme idéal, sans loi, sans corruption, sans corporation : Lostown, la ville la plus libre du monde. Mais la réalité était très loin d’être merveilleuse, violence, pauvreté, mafias, tout était presque aussi pourri qu’à Los Angeles en plus méprisable, plus misérable encore.Face à l’oppression constante des mafias locales et sans aucun recours face à elles, Faith changea d’objectif, devenant une sorte d’insurgée au sein même de Lostown, promouvant l’idée de lois, de structure et de Justice, elle reste une enders qui méprise gouvernement et corporation, mais elle rejette l’idée d’un tel chaos, elle veut le bien du peuple de Lostown, quitte à parfois être l’ennemi du concept même de la ville."}]},{"id":"antisysteme-p72-mj","title":"Dossier MJ · Anti-système","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
